import {
  addHours,
  getDaysInMonth,
  setDate,
  setHours,
  setMilliseconds,
  setMinutes,
  setMonth,
  setSeconds,
  setYear,
  startOfToday,
} from 'date-fns';
import { zonedTimeToUtc } from 'date-fns-tz';
import { useCallback, useMemo } from 'react';
import type { FormatDateOptions } from 'react-intl';
import { createIntl } from 'react-intl';

import {
  getRegionalFormat,
  getTimezone,
} from '@dynatrace-sdk/user-preferences';

import { intlCache } from '../../../formatters/intl-cache.js';
import type { DateTimePickerProps } from '../types.js';

const INVALID_DATE = new Date('Invalid');

// TODO: Use the newly introduced _useDateTimeMessages hook and avoid duplication
/** Provides functions to convert a date object to its parts and vice versa. */
export function useDateTimeFormat(
  type: DateTimePickerProps['type'] = 'datetime',
  precision: DateTimePickerProps['precision'] = 'minutes',
) {
  const regionUserSetting = getRegionalFormat();
  const timezoneUserSetting = getTimezone();

  // Create intl object based on current user settings
  const { timeZone, formatDateToParts } = useMemo(
    () =>
      createIntl(
        { locale: regionUserSetting, timeZone: timezoneUserSetting },
        intlCache,
      ),
    [regionUserSetting, timezoneUserSetting],
  );

  // Formatting rules for given type and precision combination.
  const format = useMemo(() => {
    const options: FormatDateOptions = {};
    switch (type) {
      case 'date':
        options['year'] = 'numeric';
        options['month'] = '2-digit';
        options['day'] = '2-digit';
        return options; // Return config and ignore precision prop if only the date is shown.
      case 'datetime':
        options['year'] = 'numeric';
        options['month'] = '2-digit';
        options['day'] = '2-digit';
        options['hour'] = '2-digit';
        options['minute'] = '2-digit';
        break;
      case 'time':
        options['hour'] = 'numeric';
        options['minute'] = '2-digit';
        break;
    }

    switch (precision) {
      case 'seconds':
        options['second'] = '2-digit';
        break;
      case 'milliseconds':
        options['second'] = '2-digit';
        options['fractionalSecondDigits'] = 3;
        break;
    }

    return options;
  }, [type, precision]);

  /**
   * Convert a date object to its parts for the configured format.
   * Part values are always zoned and based on the configured timezone.
   */
  const toParts = useCallback(
    (date: Date) => formatDateToParts(date, format),
    [format, formatDateToParts],
  );

  /** Convert parts to a UTC date object.  */
  const toDateTime = useCallback(
    (parts: Intl.DateTimeFormatPart[]) => {
      // every non literal part must be empty
      const isEmpty = !parts.some(
        ({ type, value }) => type !== 'literal' && value !== '',
      );

      if (isEmpty) {
        return null;
      }

      const hasDayPeriod = parts.some((p) => p.type === 'dayPeriod');

      // Calculate max nrOfDays for given year and month.
      const year = parts.find((p) => p.type === 'year')?.value;
      const month = parts.find((p) => p.type === 'month')?.value;
      const maxNrOfDays =
        year !== undefined && month !== undefined
          ? getDaysInMonth(new Date(parseInt(year), parseInt(month) - 1))
          : 31;

      const date = parts.reduce((date, part) => {
        const intValue = parseInt(part.value);
        switch (part.type) {
          case 'year':
            return setYear(date, intValue);
          case 'month':
            return setMonth(date, intValue - 1);
          case 'day':
            if (intValue > maxNrOfDays) {
              return INVALID_DATE;
            }
            return setDate(date, intValue);
          case 'hour':
            return setHours(date, hasDayPeriod ? intValue % 12 : intValue); // Treat 12 as 0 in 12h notation.
          case 'minute':
            return setMinutes(date, intValue);
          case 'second':
            return setSeconds(date, intValue);
          case 'fractionalSecond':
            return setMilliseconds(date, intValue);
          case 'dayPeriod':
            return part.value === 'PM'
              ? addHours(date, 12)
              : part.value === 'AM'
              ? date
              : INVALID_DATE;
          default:
            // Ignore time literals and other part types.
            return date;
        }
      }, startOfToday());

      // Source part values are in zoned time, offset them to UTC.
      return timeZone ? zonedTimeToUtc(date, timeZone) : date;
    },
    [timeZone],
  );

  // provide empty parts for null value in current datetime format
  const emptyParts = useMemo(
    () =>
      toParts(new Date()).map(({ type, value }) => {
        return { type, value: type === 'literal' ? value : '' };
      }),
    [toParts],
  );

  return { format, toParts, toDateTime, emptyParts };
}
